await import('odedex/app.mjs');
// Reuse the original visualizer in the expanded Archive reader.
const {OdeVisualizer}=await import('odedex/visualizer.mjs');
const {odeConfiguration}=await import('odedex/ode.mjs');
const toolRoot=document.getElementById('archiveVisualizer'),info=document.getElementById('explorerBody'),tabs=[...document.querySelectorAll('[data-reader-tab]')];
const plotKinds={scalar:'Orden 1',second:'Orden 2',system:'Sistema 2D',potential:'Potencial y plano de fases'};
const emptyTool=()=>odeConfiguration({id:'manual',title:'Exploración libre',kind:'scalar',f:'0',params:{},conditions:{type:'none'}});
let toolState=emptyTool(),readerConfigurations=[],configurationId='',configurationError='';
let readerTab='info',readerId='';
const readerVisualizer=new OdeVisualizer(toolRoot,next=>{toolState=next;if(!readerConfigurations.some(config=>config.id===next.exercise?.id))configurationId='';});
const originalRender=readerVisualizer.render.bind(readerVisualizer);
readerVisualizer.render=()=>{
  const firstRender=!toolRoot.childElementCount;
  originalRender();
  if(firstRender)toolRoot.querySelector('#ode-controls').open=false;
  toolRoot.querySelector('.ode-heading').remove();
  toolRoot.querySelector('label[for="ode-kind"]').firstChild.textContent='Tipo de gráfico';
  for(const option of toolRoot.querySelectorAll('#ode-kind option')){
    if(!Object.hasOwn(plotKinds,option.value))option.remove();else option.textContent=plotKinds[option.value];
  }
  const kindSelect=toolRoot.querySelector('#ode-kind');
  for(const kind of Object.keys(plotKinds))kindSelect.append(kindSelect.querySelector('option[value="'+kind+'"]'));
  toolRoot.querySelector('label[for="ode-example"]').remove();
  if(readerConfigurations.length){
    const label=document.createElement('label');label.htmlFor='ode-configuration';label.textContent='Vista del ejercicio';
    const select=document.createElement('select');select.id='ode-configuration';
    if(!configurationId){const manual=document.createElement('option');manual.value='';manual.textContent='Exploración libre';select.append(manual);}
    for(const config of readerConfigurations){const option=document.createElement('option');option.value=config.id;option.textContent=config.title;option.selected=config.id===configurationId;select.append(option);}
    label.append(select);toolRoot.querySelector('.ode-kind-row').prepend(label);
    select.addEventListener('change',()=>{const config=readerConfigurations.find(item=>item.id===select.value);if(!config)return;const shared=(config.problem||'principal')===(toolState.exercise?.problem||'principal')?Object.fromEntries(Object.entries(toolState.params).map(([key,p])=>[key,p.value])):{};configurationId=config.id;toolState=odeConfiguration(config,shared);readerVisualizer.set({lens:{ode:toolState}});});
  }
};
function showReaderTab(key){
  readerTab=key;
  for(const tab of tabs){const active=tab.dataset.readerTab===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}
  info.hidden=key!=='info';toolRoot.hidden=key==='info';
  if(key==='info')cancelAnimationFrame(readerVisualizer.frame);
  else{readerVisualizer.set({lens:{ode:toolState}});if(configurationError)readerVisualizer.error('No se ha podido cargar la configuración: '+configurationError+'. Puedes editar una ecuación para explorar.');}
  const dialog=document.getElementById('archivePopup');
  if(dialog.open&&dialog.dataset.panel==='context')document.getElementById('archivePopupTitle').textContent=key==='info'?'Información del ejercicio':'Visualizador';
  if(dialog.open&&key==='visualizer'&&innerWidth>760)toolRoot.querySelector('#ode-controls').open=true;
}
for(const tab of tabs){
  tab.addEventListener('click',()=>showReaderTab(tab.dataset.readerTab));
  tab.addEventListener('keydown',event=>{
    const i=tabs.indexOf(tab),next=event.key==='ArrowRight'?(i+1)%tabs.length:event.key==='ArrowLeft'?(i+tabs.length-1)%tabs.length:event.key==='Home'?0:event.key==='End'?tabs.length-1:null;
    if(next===null)return;event.preventDefault();tabs[next].focus();showReaderTab(tabs[next].dataset.readerTab);
  });
}
function syncReader(event){
  const next=document.getElementById('readerContent').dataset.readerId;
  if(next!==readerId){
    const record=event?.detail?.record||archive.records().find(item=>item.id===next);
    readerId=next;readerConfigurations=record?.visualizer||[];configurationError='';
    configurationId=readerConfigurations[0]?.id||'';
    try{toolState=readerConfigurations.length?odeConfiguration(readerConfigurations[0]):emptyTool();}
    catch(error){configurationError=error.message;readerConfigurations=[];configurationId='';toolState=emptyTool();}
    showReaderTab('info');
  }
  if(!document.getElementById('app').classList.contains('reader-focus'))cancelAnimationFrame(readerVisualizer.frame);
}
window.addEventListener('odedex:reader-render',syncReader);
syncReader();
window.addEventListener('odedex:reference-open',()=>showReaderTab('info'));
// Move the existing panel into a native dialog; keep controls and state intact.
const popup=document.getElementById('archivePopup'),popupContent=document.getElementById('archivePopupContent');
let expandedPanel=null;
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-reader-expand]');
  if(!button)return;
  const exercise=button.dataset.readerExpand==='exercise';
  if(exercise&&!document.getElementById('readerContent').dataset.readerId)return;
  const panel=document.getElementById(exercise?'readerExercise':'explorerPanel'),marker=document.createComment('expanded panel');
  const scrollNode=exercise?document.getElementById('readerContent'):readerTab==='info'?info:toolRoot;
  const scrollTop=scrollNode.scrollTop;
  const controlsOpen=toolRoot.querySelector('#ode-controls')?.open||false;
  panel.before(marker);expandedPanel={panel,marker,button,scrollNode,controlsOpen};
  document.getElementById('archivePopupTitle').textContent=exercise?'Ejercicio':readerTab==='info'?'Información del ejercicio':'Visualizador';
  popup.dataset.panel=exercise?'exercise':'context';popupContent.append(panel);popup.showModal();popupContent.scrollTop=scrollTop;
  if(!exercise&&readerTab==='visualizer'&&innerWidth>760)toolRoot.querySelector('#ode-controls').open=true;
});
document.getElementById('closeArchivePopup').addEventListener('click',()=>popup.close());
document.addEventListener('click',event=>{if(popup.open&&event.target.closest('[data-reader-action="close"]')){event.preventDefault();event.stopImmediatePropagation();popup.close();}},true);
popup.addEventListener('click',event=>{if(event.target===popup)popup.close();});
popup.addEventListener('close',()=>{
  if(!expandedPanel)return;
  const {panel,marker,button,scrollNode,controlsOpen}=expandedPanel,scrollTop=popupContent.scrollTop;
  marker.replaceWith(panel);scrollNode.scrollTop=scrollTop;expandedPanel=null;button.focus({preventScroll:true});
  const controls=toolRoot.querySelector('#ode-controls');if(controls)controls.open=controlsOpen;
});
